<div class="page-header mb-3"><div><div class="page-pretitle">Keamanan</div><h2 class="page-title"><?= html_escape($title) ?></h2></div></div><div class="card"><div class="card-body"><?php if(validation_errors()): ?><div class="alert alert-danger"><?= validation_errors() ?></div><?php endif ?><?= form_open() ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama</label><input class="form-control" name="name" value="<?= html_escape(set_value('name',$user->name??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?= html_escape(set_value('email',$user->email??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Kata sandi <?= $user?'(kosongkan jika tidak berubah)':'' ?></label><input class="form-control" type="password" name="password" autocomplete="new-password" <?= $user?'':'required' ?> minlength="10"></div><div class="col-md-6 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" value="1" <?= set_checkbox('is_active','1',!$user||$user->is_active) ?>><span class="form-check-label">Akun aktif</span></label></div><div class="col-md-6"><label class="form-label">Peran</label><?php foreach($roles as $r): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="roles[]" value="<?= $r->id ?>" <?= in_array($r->id,$selectedRoles)?'checked':'' ?>><span class="form-check-label"><?= html_escape($r->label) ?></span></label><?php endforeach ?></div><div class="col-md-6"><label class="form-label">Faskes yang dapat diakses</label><div class="form-hint mb-2">Diabaikan untuk peran dengan akses semua faskes.</div><?php foreach($branches as $b): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="branches[]" value="<?= $b->id ?>" <?= in_array($b->id,$selectedBranches)?'checked':'' ?>><span class="form-check-label"><?= html_escape($b->name) ?></span></label><?php endforeach ?><?php if(!$branches): ?><span class="text-secondary">Belum ada faskes.</span><?php endif ?></div></div><div class="mt-4 d-flex gap-2"><button class="btn btn-teal">Simpan pengguna</button><a class="btn" href="<?= site_url('users') ?>">Batal</a></div><?= form_close() ?></div></div>
